  if(data.startsWith('new:')){const [,key,value]=data.split(':');try{const state=await stateFor(q.from.id);if(key==='finish-photos'&&state?.flow==='new-property'&&state.photo){if(!(state.imageUrls||[]).length){await tg('answerCallbackQuery',{callback_query_id:q.id,text:'Avval kamida bitta rasm yuboring.',show_alert:true});return;}await tg('answerCallbackQuery',{callback_query_id:q.id});return finishPhotoStep(q.from.id,q.from,state);}if(key==='submit'&&state?.flow==='new-property'&&state.photo&&(state.imageUrls||[]).length){await tg('answerCallbackQuery',{callback_query_id:q.id,text:'Moderatorga yuborilmoqda.'});try{await saveDraft(q.from.id,q.from,state);}catch(error){console.error('bot listing submission failed:',JSON.stringify({code:error.code||'DATABASE_ERROR',column:error.column||null}));await send(q.from.id,'E’lonni yuborishda xatolik yuz berdi. Saqlangan ma’lumotlaringizni qayta yuborish uchun tugmani bosing.',{reply_markup:{inline_keyboard:[[{text:'🔄 Qayta yuborish',callback_data:'new:submit'}]]}}).catch(()=>{});}return;}const step=steps[state?.step];if(state?.flow!=='new-property'||!step||step.key!==key||!stepChoices(step,state).some(([,v])=>v===value)){await tg('answerCallbackQuery',{callback_query_id:q.id,text:'Bu tanlov eskirgan. Yangi e’lonni qayta boshlang.',show_alert:true});return;}await tg('answerCallbackQuery',{callback_query_id:q.id});await handleStep(q.from.id,q.from,'',state,value);return;}catch(e){await tg('answerCallbackQuery',{callback_query_id:q.id,text:'Tanlov saqlanmadi. Qayta urinib ko‘ring.',show_alert:true});throw e;}}
  if(data.startsWith('user:')){const [,action,id]=data.split(':');try{const u=await ensureUser(q.from);if(action==='save'||action==='unsave'){const p=await pool.query("SELECT id FROM properties WHERE id=$1 AND status='active'",[id]);if(!p.rows[0]){await tg('answerCallbackQuery',{callback_query_id:q.id,text:'Bu e’lon endi mavjud emas.',show_alert:true});return;}if(action==='save')await pool.query('INSERT INTO favorites(user_id,property_id) VALUES($1,$2) ON CONFLICT DO NOTHING',[u.id,id]);else await pool.query('DELETE FROM favorites WHERE user_id=$1 AND property_id=$2',[u.id,id]);await tg('answerCallbackQuery',{callback_query_id:q.id,text:action==='save'?'Sevimlilarga saqlandi.':'Sevimlilardan olindi.'});return;}if(action==='reply'){const c=await pool.query('SELECT id FROM conversations WHERE id=$1 AND (buyer_id=$2 OR seller_id=$2)',[id,u.id]);if(!c.rows[0]){await tg('answerCallbackQuery',{callback_query_id:q.id,text:'Suhbat topilmadi yoki ruxsat yo‘q.',show_alert:true});return;}await setState(q.from.id,{flow:'reply',conversationId:id});await tg('answerCallbackQuery',{callback_query_id:q.id});await send(q.message.chat.id,'Javob matnini yozing (4000 belgigacha).');return;}if(action==='ask'){const p=await pool.query("SELECT owner_id FROM properties WHERE id=$1 AND status='active'",[id]);if(!p.rows[0]||p.rows[0].owner_id===u.id){await tg('answerCallbackQuery',{callback_query_id:q.id,text:p.rows[0]?'O‘z e’loningizga yozolmaysiz.':'Bu e’lon hozir mavjud emas.',show_alert:true});return;}await setState(q.from.id,{flow:'ask',propertyId:id});await tg('answerCallbackQuery',{callback_query_id:q.id});await send(q.message.chat.id,'Sotuvchiga yuboriladigan savolingizni yozing (4000 belgigacha).');return;}if(action==='apply'){await tg('answerCallbackQuery',{callback_query_id:q.id});return handleApply(q.message.chat.id,q.from,id);}await tg('answerCallbackQuery',{callback_query_id:q.id,text:'Amal tanilmadi.'});}catch(e){await tg('answerCallbackQuery',{callback_query_id:q.id,text:'Amal bajarilmadi. Qayta urinib ko‘ring.',show_alert:true});throw e;}return;}
