  if(text==='/favorites'){const u=await ensureUser(from);const {rows}=await pool.query(`SELECT p.id,p.title,p.price,p.area,p.area_unit,p.region,p.district FROM favorites f JOIN properties p ON p.id=f.property_id WHERE f.user_id=$1 AND p.status='active' ORDER BY f.created_at DESC LIMIT 20`,[u.id]);return sendProperties(chatId,rows,'favorites');}
